per_case_results.actual_sql:
SELECT ((a."overall_rating" - p."overall_rating") * 100.0 / p."overall_rating") AS percentage_difference
FROM (SELECT "overall_rating" FROM "players" WHERE "player_name" = 'Ariel Borysiuk') AS a,
     (SELECT "overall_rating" FROM "players" WHERE "player_name" = 'Paulin Puel') AS p;

SELECT "buildUpPlaySpeedClass"
FROM "teams"
WHERE "team_long_name" = 'KSV Cercle Brugge';
